<template>
<div class="dashboard">
  <div class="page-heading"><div><p class="dashboard-date">{{today}}</p><h2>{{ greeting }}，{{profile.realName || profile.username || '活动管理员'}}</h2><p>从这里开始，让每一场校园活动有序发生。</p></div><el-button type="primary" @click="$router.push('/activity/create')"><AppIcon name="plus" :size="17"/>新建活动</el-button></div>
  <div v-if="error" class="page-state"><strong>暂时无法加载工作台</strong><p>{{error}}</p><el-button @click="load">重新加载</el-button></div>
  <div v-else v-loading="loading">
    <section class="metrics-panel" aria-label="近30天活动数据"><div v-for="item in metrics" :key="item.key" class="metric"><div class="metric-label"><span>{{item.label}}</span><AppIcon :name="item.icon" :size="17"/></div><strong>{{totals[item.key] ?? '—'}}<small v-if="item.key==='checkinRate'">%</small></strong><p>{{item.note}}</p></div></section>
    <div class="scope-line"><span>近 30 天创建的有效活动</span><span>{{profile.roleCode==='SUPER'?'全平台数据':'所属组织数据'}}</span></div>
    <div class="dashboard-columns">
      <section class="surface recent-section"><div class="section-title"><div><h3>最近活动</h3><p>近期安排，一目了然。</p></div><router-link to="/activity">全部活动 <AppIcon name="arrow" :size="15"/></router-link></div>
        <div v-if="!recent.length" class="page-state"><AppIcon name="activity" :size="30"/><p>还没有活动，开始组织第一场吧。</p><el-button @click="$router.push('/activity/create')">创建活动</el-button></div>
        <router-link v-for="item in recent" :key="item.activityId" :to="`/activity/${item.activityId}`" class="recent-row"><div class="calendar-tile"><span>{{datePart(item.startTime,'month')}}月</span><strong>{{datePart(item.startTime,'day')}}</strong></div><div class="recent-info"><strong>{{item.title}}</strong><small>{{item.location}} · {{formatTime(item.startTime).slice(0,16)}}</small></div><div class="recent-meta"><span class="status-dot" :class="item.status.toLowerCase()">{{statusLabels[item.status] || item.status}}</span><small>{{item.signedCount}} / {{item.quota}} 人</small></div><AppIcon class="row-arrow" name="arrow" :size="16"/></router-link>
      </section>
      <aside class="dashboard-side">
        <section class="review-panel"><div class="review-top"><span>审批待办</span><AppIcon name="review" :size="20"/></div><div class="review-count">{{pending}}<small>项待处理</small></div><p>{{pending?'查看申请内容与审批进度，及时推进活动。':'当前没有待审申请，所有安排井然有序。'}}</p><router-link to="/platform/reviews">进入审批中心 <AppIcon name="arrow" :size="17"/></router-link></section>
        <section class="surface quick-section"><h3>常用入口</h3><router-link class="quick-link" to="/statistics"><span class="quick-icon"><AppIcon name="chart"/></span><div><strong>参与情况</strong><small>报名、到场与活动趋势</small></div><AppIcon name="arrow" :size="16"/></router-link><router-link v-if="profile.roleCode==='SUPER'" class="quick-link" to="/platform/organizations"><span class="quick-icon"><AppIcon name="organization"/></span><div><strong>组织空间</strong><small>管理组织与协作权限</small></div><AppIcon name="arrow" :size="16"/></router-link><router-link v-else class="quick-link" to="/activity"><span class="quick-icon"><AppIcon name="activity"/></span><div><strong>活动档案</strong><small>查看所属组织的活动</small></div><AppIcon name="arrow" :size="16"/></router-link></section>
      </aside>
    </div>
  </div>
</div>
</template>
<script setup>
import {onMounted,ref} from 'vue'
import {authApi,statisticsApi,activityApi,reviewApi} from '../../api'
import {formatTime} from '../../utils/display'
import AppIcon from '../../components/AppIcon.vue'
const today=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date())
const hour=new Date().getHours(),greeting=hour<12?'上午好':hour<18?'下午好':'晚上好'
const pending=ref(0),totals=ref({}),recent=ref([]),profile=ref({}),loading=ref(true),error=ref('')
const metrics=[{key:'activityCount',label:'有效活动',icon:'activity',note:'场校园活动'},{key:'signupCount',label:'报名人次',icon:'people',note:'人次参与报名'},{key:'checkinCount',label:'到场人次',icon:'check',note:'人次完成签到'},{key:'checkinRate',label:'签到率',icon:'chart',note:'已签到 / 已报名'}]
const statusLabels={DRAFT:'未发布',OPEN:'报名中',CLOSED:'已截止',ONGOING:'进行中',FINISHED:'已结束',CANCELED:'已取消'}
function datePart(value,part){const s=String(value||'');return s.length>=10?String(Number(s.slice(part==='month'?5:8,part==='month'?7:10))):'—'}
async function load(){loading.value=true;error.value='';try{const [a,b,c,d]=await Promise.all([statisticsApi.overview(),activityApi.page({current:1,size:6}),authApi.current(),reviewApi.queue({current:1,size:1,decision:'PENDING'})]);totals.value=a;recent.value=b.records;profile.value=c;pending.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>
<style scoped>
