-size:13px;font-weight:550}.recent-info small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:#839187;margin-top:6px}.recent-meta{text-align:right;white-space:nowrap}.recent-meta>small{display:block;font-size:10px;color:#8a988f;margin-top:7px}.status-dot{font-size:11px;color:#7f8d83}.status-dot:before{content:'';display:inline-block;width:5px;height:5px;border-radius:50%;background:#a9b5ac;margin-right:6px;vertical-align:middle}.status-dot.open:before,.status-dot.ongoing:before{background:#4b9870}.status-dot.open,.status-dot.ongoing{color:#43765a}.row-arrow{color:#b0bab1}.dashboard-side{display:grid;gap:22px}.review-panel{padding:26px;background:#214e3f;color:#fff;border-radius:12px}.review-top{display:flex;align-items:center;justify-content:space-between;font-size:13px;color:#c5d7cc}.review-count{font-size:44px;line-height:1.2;letter-spacing:-.04em;margin:24px 0 14px;font-weight:550;font-variant-numeric:tabular-nums}.review-count small{font-size:12px;font-weight:400;color:#b6cabe;margin-left:12px;letter-spacing:0}.review-panel p{font-size:12px;color:#b6cabe;line-height:1.9;max-width:260px;margin-bottom:24px}.review-panel a{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #406957;padding-top:18px;font-size:12px;color:#f1f7f1}.quick-section h3{margin-bottom:8px}.quick-link{display:flex;align-items:center;gap:12px;padding:19px 0;border-bottom:1px solid #edf0eb;color:#435e4b}.quick-link:last-child{border:0;padding-bottom:0}.quick-icon{width:37px;height:37px;display:grid;place-items:center;background:#f3f6ef;border-radius:8px;color:#7b9680}.quick-link>div{flex:1}.quick-link strong{font-size:12px;font-weight:550}.quick-link small{display:block;font-size:11px;color:#87958a;margin-top:3px}.quick-link>svg{color:#a8b4aa}
@media(max-width:1100px){.dashboard-columns{grid-template-columns:1fr}.dashboard-side{grid-template-columns:1fr 1fr}.metric{padding:0 20px}}@media(max-width:700px){.page-heading{align-items:flex-start}.page-heading h2{font-size:24px}.page-heading .el-button{padding:0 12px;flex-shrink:0}.dashboard-columns{gap:18px}.metrics-panel{grid-template-columns:repeat(2,minmax(0,1fr));padding:0}.metric{padding:20px;border-bottom:1px solid #edf0ea}.metric:nth-child(2){border-right:0}.metric:nth-child(n+3){border-bottom:0}.metric>strong{font-size:32px}.dashboard-side{grid-template-columns:1fr}.surface{padding:20px}.row-arrow{display:none}.recent-row{gap:12px}.calendar-tile{width:40px;min-width:40px}.recent-meta{max-width:88px}.scope-line{margin-bottom:24px}}
</style>
